def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_coops = 0
    my_coops = 0
    tail_def = 0
    tail_cc = 0
    for me, them in history:
        if them == 'C':
            opp_coops += 1
        if me == 'C':
            my_coops += 1

    for me, them in reversed(history):
        if them == 'D':
            tail_def += 1
        else:
            break
    for me, them in reversed(history):
        if me == 'C' and them == 'C':
            tail_cc += 1
        else:
            break

    opp_rate = opp_coops / n
    recent = history[-min(12, n):]
    recent_opp_c = sum(1 for _, o in recent if o == 'C')
    recent_rate = recent_opp_c / len(recent)

    last_opp = history[-1][1]
    last_me = history[-1][0]

    # Punish persistent defection
    if tail_def >= 3:
        # try rare reset only if opponent was previously quite cooperative
        if opp_coops * 4 >= n * 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if opp_rate < 0.25:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Very cooperative opponent: occasionally defect late to exploit
    if opp_rate > 0.9:
        if n > 75 and rng.random() < 0.3:
            return 'D'
        if n > 20 and rng.random() < 0.04:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'C':
            # retaliate unless strongly cooperative, with some tolerance
            if opp_rate > 0.7 and n > 5 and rng.random() < 0.35:
                return 'C'
            return 'D'
        # both defected, don't spiral too much if mostly cooperative
        if opp_rate > 0.6 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # last_opp == 'C'
    if last_me == 'D':
        # return to cooperation
        if rng.random() < 0.92:
            return 'C'
        return 'D'

    if recent_rate < opp_rate - 0.35 and len(recent) >= 5:
        return 'D'

    if n > 80:
        if opp_rate < 0.5:
            return 'D'
        if n % 4 == 0 and opp_rate > 0.55:
            return 'D'
        return 'C'

    # If long mutual cooperation streak, rarely test
    if tail_cc >= 6 and n > 10:
        if rng.random() < 0.07:
            return 'D'
        return 'C'

    if opp_rate < 0.5:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    return 'C'
